// Isolated interaction study. Everything here is synthetic and browser-local.
const $=s=>document.querySelector(s), escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles=['Cabin weekend for two','Dinner at the chef’s table','Ceramics workshop','A little luxury at home','Coastal escape','Coffee for a year','An evening at the theatre','Handmade walnut bowl','A night under the stars','Wine tasting for six','Private garden tour','Sunday morning essentials','Two nights in wine country','The neighbourhood supper club','Photography walk','A beautifully stocked pantry','Mountain lodge retreat','Pizza party for twelve','A day on the water','Locally made linen set','A slower weekend away','Baker’s breakfast box','A lesson with the pro','A home for good books','City hotel stay','Farm-to-table hamper','An artist’s afternoon','The gathering board','Lakeside hideaway','Your next favourite restaurant'];
const cats=['Travel','Food & drink','Experiences','Home'],tones=['#355b4e','#795438','#5b506b','#33415c'];
let flow=new URLSearchParams(location.search).get('flow')==='drafts'?'drafts':'automatic', data,group='all',selected=new Set(),editing=null,returnFocus=null,saveTimer,toastTimer;
const key=()=>`bz_items_study_v1_${flow}`;
function defaults(){return{mode:'draft',items:titles.map((title,n)=>({id:'example-'+n,title,category:cats[n%4],amount:[150,75,100,50][n%4],donor:['Juniper Design','Oak & Table','Saturn members','North Studio'][n%4],description:'A thoughtful contribution from our community.',ready:n<26,photo:n%7!==0?'art':null}))};}
function load(){try{data=JSON.parse(localStorage.getItem(key()))??defaults();}catch{data=defaults();}if(!Array.isArray(data.items))data=defaults();}
function persist(){localStorage.setItem(key(),JSON.stringify(data));$('#saved').textContent='Saving…';if($('#edit-saved'))$('#edit-saved').textContent='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{$('#saved').textContent='Saved on this browser';if($('#edit-saved'))$('#edit-saved').textContent='Saved';},500);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('on'),3500);}
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function thumb(item){return `<span class="thumb${item.photo?'':' empty'}" style="--tone:${tones[Math.max(0,cats.indexOf(item.category))]}">${item.photo&&item.photo!=='art'?`<img src="${escape(item.photo)}" alt="">`:item.photo?String(data.items.indexOf(item)+1).padStart(2,'0'):'＋'}</span>`;}
function render(){
 $('#flow').value=flow;$('#event-mode').value=data.mode;$('#event-note').textContent=data.mode==='live'?'Live · saved edits appear to guests.':'Draft · only staff can see this event.';
 $('#count').textContent=data.items.length;
 $('#flow-note').textContent=flow==='automatic'?'Edit freely. Keep a draft only when you need one.':'Prepare in Drafts, then add finished items to the event.';
 const groups=flow==='drafts'?[['all','All items'],['draft','Drafts'],['event','In the event']]:[];
 $('#groups').innerHTML=groups.map(([id,name])=>`<button class="${group===id?'on':''}" data-group="${id}" aria-pressed="${group===id}">${name} <small>${data.items.filter(i=>id==='all'||(id==='draft'?!i.ready:i.ready)).length}</small></button>`).join('');
 const search=$('#search').value.toLowerCase(),category=$('#category').value,missing=$('#missing').checked;
 const shown=data.items.filter(i=>(group==='all'||(group==='draft'?!i.ready:i.ready))&&(!category||i.category===category)&&(!missing||!i.photo)&&[i.title,i.donor,i.category].some(t=>t.toLowerCase().includes(search)));
 $('#list').innerHTML=`<div class="row header"><span></span><span>Item</span><span>Name / donor</span><span>Category</span><span>Starting at</span><span>Availability</span><span></span></div>`+(shown.length?shown.map(i=>`<div class="row"><input type="checkbox" data-select="${i.id}" aria-label="Select ${escape(i.title||'Untitled item')}" ${selected.has(i.id)?'checked':''}>${thumb(i)}<button class="itemname" data-edit="${i.id}"><b>${escape(i.title||'Untitled item')}</b><small>${i.ready?escape(i.donor):'Draft · only staff can see'}</small></button><span class="category">${escape(i.category)||'—'}</span><span class="amount">${money(i.amount)}</span><span class="availability ${i.ready?'':'draft'}">${i.ready?'In the event':'Draft'}</span><span class="arrow">›</span></div>`).join(''):`<div class="empty-state"><h3>No items here yet.</h3><p>Try another filter, or add an item.</p></div>`);
 $('#showing').textContent=`${shown.length} of ${data.items.length} items`;
 const drafts=data.items.filter(i=>selected.has(i.id)&&!i.ready);
 $('#selection').hidden=!selected.size;$('#selection').innerHTML=`<span>${selected.size} selected${drafts.length?` · ${drafts.length} draft${drafts.length===1?'':'s'}`:''}</span>${drafts.length?'<button class="button primary" id="add-selected">Add to event</button>':''}<button class="button" id="clear-selected">Clear</button>`;
}
function navigate(hash){location.hash=hash;}
function close(){navigate('');}
function modal(html){$('#overlay').innerHTML=`<div class="scrim">${html}</div>`;document.body.classList.add('modal');}
function route(){
 const hash=location.hash.slice(1);if(!hash){$('#overlay').innerHTML='';document.body.classList.remove('modal');editing=null;render();if(returnFocus?.dataset.edit)document.querySelector(`[data-edit="${returnFocus.dataset.edit}"]`)?.focus();else if(returnFocus?.id)document.getElementById(returnFocus.id)?.focus();return;}
 if(hash==='preview')return preview();if(hash==='many')return bulk();if(hash.startsWith('item/')){const item=data.items.find(i=>i.id===hash.slice(5));if(item)return editor(item);}close();
}
function editor(item){
 editing=item.id;
 const note=item.ready?(data.mode==='live'?'In the event · every saved edit appears to guests.':'In the event · guests will see it when the event goes live.'):'Draft · saved for staff only. Add it to the event when it’s ready.';
 modal(`<section class="editor" role="dialog" aria-modal="true" aria-labelledby="editor-title"><div class="editorhead"><h2 id="editor-title">${item.ready?'Edit item':'Prepare item'}</h2><span class="editstate" id="edit-saved">Saved</span><button class="close" aria-label="Close item">×</button></div><div class="editorbody"><p class="note">${note}</p><label class="field">Item name<input id="item-title" data-field="title" value="${escape(item.title)}" placeholder="What’s up for bidding?" maxlength="200"></label><label class="phototarget">${item.photo?thumb(item):'<span>＋ Add a photo · click or drop</span>'}<input type="file" id="photo" accept="image/png,image/jpeg,image/webp" aria-label="Item photo"></label><div class="pair"><label class="field">Starting amount ($)<input data-field="amount" type="number" min="1" step="1" value="${item.amount}"></label><label class="field">Category<select data-field="category"><option value="">Uncategorized</option>${cats.map(c=>`<option ${c===item.category?'selected':''}>${escape(c)}</option>`).join('')}</select></label></div><label class="field">Donor<input data-field="donor" value="${escape(item.donor)}" maxlength="200" placeholder="Optional"></label><label class="field">Description<textarea data-field="description" maxlength="10000">${escape(item.description)}</textarea></label><p class="study-note">Photos and edits stay in this browser. This study does not change a real event.</p></div><div class="editorfoot">${item.ready?'<button class="button primary" id="done-item">Done</button>':'<button class="button" id="keep-draft">Keep as draft</button><button class="button primary" id="finish-item">Add to event</button>'}</div></section>`);
 $('#item-title').focus();
 $('.phototarget').ondragover=e=>e.preventDefault();$('.phototarget').ondrop=e=>{e.preventDefault();photo(e.dataTransfer.files[0]);};
}
function add(){const item={id:crypto.randomUUID(),title:'',category:'',amount:100,donor:'',description:'',ready:flow==='automatic'&&data.mode==='draft',photo:null};data.items.push(item);persist();render();navigate('item/'+item.id);}
function photo(file){if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>8*1024*1024){toast('Choose a JPEG, PNG or WebP smaller than 8 MB.');return;}const id=editing,reader=new FileReader();reader.onload=()=>{const i=data.items.find(x=>x.id===id);if(!i)return;i.photo=reader.result;try{persist();}catch{i.photo=null;toast('Browser storage is full. Try a smaller photo.');}if(editing===id)editor(i);};reader.readAsDataURL(file);}
function finish(ids){const items=data.items.filter(i=>ids.includes(i.id));if(items.some(i=>!i.title.trim()||!Number.isFinite(i.amount)||i.amount<1)){toast('Add a name and starting amount first.');return;}items.forEach(i=>i.ready=true);persist();selected.clear();close();render();toast(data.mode==='live'?`${items.length===1?'Item is':items.length+' items are'} now visible to guests.`:'Added to the event. Keep editing anytime.');}
function preview(){const items=data.items.filter(i=>i.ready);modal(`<section class="guest" role="dialog" aria-modal="true" aria-label="Synthetic guest preview"><div class="guestinner"><div class="guesthead"><span class="brand">bid<span>zizi</span></span><button class="button close">Back to items</button></div><p class="previewnotice">Synthetic guest preview · ${items.length} items in the event.${data.mode==='draft'?' The event is still a draft; real guests could not enter yet.':''} Draft items are excluded.</p><h1>Good company.<br>Great finds.</h1><p class="subtitle">Holiday Trade Show · Saturn</p><div class="guestgrid" style="margin-top:24px">${items.map(i=>`<article class="guestcard">${thumb(i)}<div><h3>${escape(i.title||'Untitled item')}</h3><p>Starts at <b>${money(i.amount)}</b></p></div></article>`).join('')}</div></div></section>`);$('.close').focus();}
function bulk(){modal(`<section class="editor bulk" role="dialog" aria-modal="true" aria-labelledby="bulk-title"><div class="editorhead"><h2 id="bulk-title">Add several items</h2><button class="close" aria-label="Close add several">×</button></div><div class="editorbody"><p>Paste rows from a spreadsheet: <b>name, starting amount, category, donor</b>. Use one item per line, with tabs between columns.</p><label class="field">Your rows<textarea id="paste" placeholder="Cabin weekend&#9;150&#9;Travel&#9;Juniper&#10;Dinner for two&#9;75&#9;Food &amp; drink&#9;Oak &amp; Table"></textarea></label><button class="button" id="review-rows">Review rows</button><div id="bulkrows" class="bulkrows" style="margin-top:16px"></div></div><div class="editorfoot"><button class="button primary" id="confirm-rows" disabled>Add items</button></div></section>`);$('#paste').focus();}
let pendingRows=[];
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.classList.contains('close')||b.id==='done-item'||b.id==='keep-draft')return close();
 if(b.dataset.edit){returnFocus=b;return navigate('item/'+b.dataset.edit);}
 if(b.dataset.group){group=b.dataset.group;selected.clear();return render();}
 if(['add','preview','many'].includes(b.id))returnFocus=b;
 if(b.id==='add')return add();if(b.id==='preview')return navigate('preview');if(b.id==='many')return navigate('many');
 if(b.id==='finish-item')return finish([editing]);if(b.id==='add-selected')return finish([...selected]);if(b.id==='clear-selected'){selected.clear();return render();}
 if(b.id==='reset'){data=defaults();group='all';selected.clear();persist();close();render();toast('Example reset.');}
 if(b.id==='review-rows'){
  const lines=$('#paste').value.trim().split('\n').filter(Boolean);pendingRows=[];const messages=[];
  lines.forEach((line,n)=>{const [title,amount,category='',donor='']=line.split('\t'),value=Number(amount?.replace(/[$,]/g,''));if(!title?.trim()||!amount?.trim()||!Number.isFinite(value)||value<1){messages.push(`<div>Row ${n+1}: add a name and a starting amount.</div>`);return;}pendingRows.push({id:crypto.randomUUID(),title:title.trim(),amount:value,category:category.trim(),donor:donor.trim(),description:'',photo:null,ready:flow==='automatic'&&data.mode==='draft'});messages.push(`<div><b>${escape(title)}</b> · ${money(value)} · ${escape(category)||'Uncategorized'}</div>`);});
  $('#bulkrows').innerHTML=messages.join('');$('#confirm-rows').disabled=!pendingRows.length||pendingRows.length!==lines.length;$('#confirm-rows').textContent=flow==='drafts'||data.mode==='live'?`Add ${pendingRows.length} drafts`:`Add ${pendingRows.length} items`;
 }
 if(b.id==='confirm-rows'&&pendingRows.length){data.items.push(...pendingRows);persist();const n=pendingRows.length;pendingRows=[];close();render();toast(`${n} items added. Add photos whenever you’re ready.`);}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field&&editing){const item=data.items.find(i=>i.id===editing);if(!item)return;item[el.dataset.field]=el.dataset.field==='amount'?Number(el.value):el.value;persist();}if(el.id==='search')render();if(el.id==='paste'){$('#confirm-rows').disabled=true;pendingRows=[];}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.select){el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);render();}if(el.id==='missing'||el.id==='category')render();if(el.id==='event-mode'){data.mode=el.value;persist();render();}if(el.id==='photo')photo(el.files[0]);if(el.id==='flow'){flow=el.value;group='all';selected.clear();load();history.replaceState(null,'',`?flow=${flow}`);$('#overlay').innerHTML='';document.body.classList.remove('modal');render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&location.hash)close();if(e.key==='Tab'&&document.body.classList.contains('modal')){const els=[...$('#overlay').querySelectorAll('button:not(:disabled),input,select,textarea,[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',route);load();render();route();
